def transform(grid):
    # The divider is the column of 2s. The two sides are overlaid after
    # removing their background colors; output marks the non-background
    # features appearing on either side, in the left panel's coordinates.
    h, w = len(grid), len(grid[0])
    sep = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]

    def background(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    lb, rb = background(left), background(right)
    return [[3 if a != lb or b != rb else 5
             for a, b in zip(lrow, rrow)]
            for lrow, rrow in zip(left, right)]
